H.text("Graham's law of effusion:  rate is proportional to 1 / sqrt(M)", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Lighter gases effuse faster; rate ratio = sqrt(M_ref / M)", 24, 52, { color: H.colors.sub, size: 13 });
const M = Math.max(2, P.M);
const Mref = 4;
const rTest = 1 / Math.sqrt(M);
const rRef = 1 / Math.sqrt(Mref);
const ratio = Math.sqrt(Mref / M);
function chamber(cy, label, rate, col) {
  const bx = 70, bw = 230, bh = 150;
  const by = cy - bh / 2;
  H.rect(bx, by, bw, bh, { stroke: H.colors.grid, width: 3, radius: 8 });
  H.line(bx + bw, by + bh / 2 - 10, bx + bw, by + bh / 2 + 10, { color: H.colors.bg, width: 6 });
  H.text(label, bx + 8, by + 18, { color: col, size: 13, weight: 700 });
  for (let i = 0; i < 10; i++) {
    const ph = i * 1.4;
    const x = bx + 25 + ((i * 41) % (bw - 50)) + 8 * Math.sin(t * (2 + rate * 30) + ph);
    const y = by + 25 + ((i * 53) % (bh - 50)) + 8 * Math.cos(t * (2 + rate * 30) + ph);
    H.circle(x, y, 6, { fill: col });
  }
  const span = 260;
  for (let kk = 0; kk < 5; kk++) {
    const prog = ((t * rate * 22 + kk * 0.2) % 1);
    const ex = bx + bw + prog * span;
    const ey = cy + 6 * Math.sin(prog * 6 + kk);
    H.circle(ex, ey, 5, { fill: col });
  }
}
chamber(150, "Test gas  M = " + M.toFixed(0) + " g/mol", rTest, H.colors.accent2);
chamber(360, "He reference  M = 4 g/mol", rRef, H.colors.good);
